def eulerian_num(n, m):
    if m >= n or n == 0:
        return 0
    if m == 0:
        return 1
    if n == 1:
        return 0
    if m == 1:
        return n - 1

    # Initialize the base cases
    A = [[0] * (m + 1) for _ in range(n + 1)]
    A[0][0] = 1

    # Fill the table using the recurrence relation
    for i in range(1, n + 1):
        A[i][0] = (i - 1) * A[i - 1][1]
        for j in range(1, min(i, m) + 1):
            A[i][j] = (i - 1) * (A[i - 1][j] + A[i - 1][j - 1])

    return A[n][m]

# Example usage:
print(eulerian_num(5, 2))  # Output: 15

def list_to_float(test_list):
    # Iterate over each sublist in the main list
    for sub_list in test_list:
        # Iterate over each element in the sublist
        for i in range(len(sub_list)):
            # Check if the element can be converted to float
            try:
                # Convert the element to float
                sub_list[i] = float(sub_list[i])
            except ValueError:
                # If conversion fails, leave the element unchanged
                pass
    return test_list

# Example usage:
test_list = [["1", "2", "3"], ["4", "5", "6"], ["7", "8", "9"]]
print(list_to_float(test_list))

def div_sum(n):
    # Calculate the sum of divisors of n
    return sum(i for i in range(1, n + 1) if n % i == 0)

# Example usage:
# print(div_sum(28))  # Output: 28
# print(div_sum(12))  # Output: 28

from typing import Optional

def find_solution(a: int, b: int, n: int) -> Optional[tuple]:
    # Check if a and b are coprime
    if gcd(a, b) != 1:
        return None

    # Extended Euclidean algorithm to find x and y
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd, x1, y1 = extended_gcd(y, x % y)
        x = y1
        y = x1 - (x // y) * y1
        return gcd, x, y

    gcd, x, y = extended_gcd(a, b)

    # If gcd is not 1, no solution exists
    if gcd != 1:
        return None

    # Scale the solution to match the equation ax + by = n
    k = n // gcd
    return (k * x, k * y)

# Helper function to calculate the greatest common divisor
def gcd(x, y):
    while y:
        x, y = y, x % y
    return x
